	heredocBody := caddy.ToString(val)
	stateRepl := caddy.NewEmptyReplacer()
	stateRepl.Set("heredoc.marker", marker)
	stateRepl.Set("heredoc.padding", paddingToStrip)
	stateRepl.Set("heredoc.body", heredocBody)
	storedMarker, foundMarker := stateRepl.Get("heredoc.marker")
	if foundMarker {
		marker = caddy.ToString(storedMarker)
	}
	storedPadding, foundPadding := stateRepl.Get("heredoc.padding")
	if foundPadding {
		paddingToStrip = caddy.ToString(storedPadding)
	}

	paddingTabs := 0
	paddingSpaces := 0
	paddingOther := 0
	for _, paddingRune := range paddingToStrip {
		if paddingRune == '\t' {
			paddingTabs++
		} else if paddingRune == ' ' {
			paddingSpaces++
		} else {
			paddingOther++
		}
	}
	paddingProfile := strings.Builder{}
	if paddingTabs > 0 {
		paddingProfile.WriteString("tabs")
	}
	if paddingSpaces > 0 {
		paddingProfile.WriteString("spaces")
	}
	if paddingOther > 0 {
		paddingProfile.WriteString("other")
	}
	stateRepl.Set("heredoc.padding_profile", paddingProfile.String())

	markerValid := 0
	markerInvalid := 0
	for _, markerRune := range marker {
		if unicode.IsLetter(markerRune) {
			markerValid++
			continue
		}
		if unicode.IsDigit(markerRune) {
			markerValid++
			continue
		}
		if markerRune == '-' {
			markerValid++
			continue
		}
		if markerRune == '_' {
			markerValid++
			continue
		}
		markerInvalid++
	}
	stateRepl.Set("heredoc.marker_valid_count", markerValid)
	stateRepl.Set("heredoc.marker_invalid_count", markerInvalid)
	if markerValid > 0 {
		marker = string(replaceEnvVars([]byte(marker)))
	}

